<template>
  <div><div class="row items-center justify-between q-mb-md"><div class="text-h5">保單</div><q-btn v-if="canCreate" color="primary" label="新增保單" icon="add" @click="$inertia.visit(route('admin.insurance-policies.create'))" /></div><q-card><q-card-section><q-table :rows="policies" :columns="columns" row-key="id" flat><template #body-cell-is_active="props"><q-td :props="props"><q-badge :color="props.value ? 'positive' : 'grey'">{{ props.value ? '啟用' : '停用' }}</q-badge></q-td></template><template #body-cell-actions="props"><q-td :props="props"><q-btn v-if="canEdit" flat round dense icon="edit" @click="$inertia.visit(route('admin.insurance-policies.edit', props.row.id))" /><q-btn v-if="canDelete" flat round dense color="negative" icon="delete" @click="selected = props.row; showDelete = true" /></q-td></template></q-table></q-card-section></q-card><q-dialog v-model="showDelete"><q-card><q-card-section class="text-h6">刪除保單</q-card-section><q-card-section>確定要刪除「{{ selected?.policy_code }}」嗎？</q-card-section><q-card-actions align="right"><q-btn flat label="取消" v-close-popup /><q-btn flat color="negative" label="刪除" @click="remove" /></q-card-actions></q-card></q-dialog></div>
</template>
<script setup lang="ts">
import { ref } from 'vue'; import { router } from '@inertiajs/vue3'; import AdminLayout from '../../Layouts/AdminLayout.vue'; import { useCan } from '../../Composables/useCan'
defineOptions({ layout: AdminLayout }); type Policy = { id:number; company_name:string; company_code:string; policy_code:string; name:string; version:string; effective_date:string|null; is_active:boolean; contents_count:number }; defineProps<{ policies: Policy[] }>(); const { can: canCreate }=useCan('admin.insurance-policies.create'); const { can:canEdit}=useCan('admin.insurance-policies.edit'); const { can:canDelete}=useCan('admin.insurance-policies.delete'); const showDelete=ref(false); const selected=ref<Policy|null>(null); const columns=[{name:'company_code',label:'保險公司',field:(row:Policy)=>`${row.company_code} - ${row.company_name}`,align:'left'},{name:'policy_code',label:'保單代號',field:'policy_code',align:'left'},{name:'name',label:'保單名稱',field:'name',align:'left'},{name:'version',label:'版本',field:'version',align:'left'},{name:'contents_count',label:'內文數',field:'contents_count',align:'right'},{name:'is_active',label:'狀態',field:'is_active',align:'center'},{name:'actions',label:'操作',field:'actions',align:'right'}]; const remove=()=>selected.value&&router.delete(route('admin.insurance-policies.destroy',selected.value.id),{onSuccess:()=>showDelete.value=false})
</script>
